const e=[{title:"Why RAG?",subtitle:"Grounding LLMs in Your Data",bullets:[{text:"LLMs alone lack private, up-to-date, or domain-specific knowledge.",icon:"llm"},{text:"RAG retrieves relevant documents at query time and injects them into the prompt.",icon:"rag"},{text:"Reduces hallucination risk and lets you cite sources in enterprise settings.",icon:"warning"}],speakerNote:"Open with a failed pure-LLM answer on internal policy — then show the same question with retrieved docs.",titleIcon:"llm",conceptAnimation:"rag-pipeline"},{title:"RAG Pipeline Overview",subtitle:"Index → Retrieve → Augment → Generate",bullets:[{text:"Offline: chunk documents → embed → store in a vector index.",icon:"embedding"},{text:"Online: embed user query → retrieve top-k chunks → build augmented prompt.",icon:"embedding"},{text:"LLM generates answer conditioned on retrieved context.",icon:"llm"}],note:"Think of RAG as search + synthesis, not search alone.",speakerNote:"Draw the four boxes on the board; emphasize offline vs online paths.",titleIcon:"rag",conceptAnimation:"rag-pipeline"},{title:"Chunking Strategies",bullets:[{text:"Fixed-size windows (e.g., 512 tokens) — simple but may split semantics.",icon:"tree"},{text:"Semantic / paragraph chunks — better coherence, variable length.",icon:"rag"},{text:"Overlap between chunks improves recall for boundary facts.",icon:"metric"}],speakerNote:"Demo: same paragraph split badly vs well — show retrieval difference.",titleIcon:"idea"},{title:"Embeddings & Vector Stores",table:{headers:["Component","Role","Examples"],rows:[["Embedding model","Maps text to dense vectors","OpenAI, Cohere, sentence-transformers"],["Vector DB","Similarity search at scale","FAISS, Pinecone, Chroma, pgvector"],["Metadata","Filter by tenant, date, ACL","JSON fields on each chunk"]]},speakerNote:"Stress metadata filters for multi-tenant enterprise deployments.",titleIcon:"embedding",illustration:"embedding-space"},{title:"Retrieval Quality",bullets:[{text:"Recall@k: did the right chunk appear in top results?",icon:"metric"},{text:"Hybrid search (BM25 + vectors) often beats either alone.",icon:"embedding"},{text:"Re-rankers can sharpen top results before the LLM sees them.",icon:"llm"}],speakerNote:"Ask: what happens if the correct chunk ranks #11 with k=5?",titleIcon:"idea"},{title:"Prompt Construction for RAG",body:"A robust template states rules, lists sources, then asks the question.",bullets:[{text:"Instruct the model to answer only from provided context.",icon:"model"},{text:"Include chunk boundaries and source IDs for traceability.",icon:"rag"},{text:"Handle empty retrieval with a safe fallback message.",icon:"rag"}],speakerNote:"Show a minimal prompt template trainees can copy.",titleIcon:"rag",conceptAnimation:"rag-pipeline"},{title:"Faithfulness & Hallucination",bullets:[{text:"Even with context, models may invent facts — evaluate faithfulness.",icon:"test"},{text:"Ask the model to quote supporting spans when possible.",icon:"model"},{text:"Human review for high-stakes domains (legal, medical, finance).",icon:"idea"}],speakerNote:"Run a live example where the model ignores a contradicting chunk.",titleIcon:"idea"},{title:"RAG Evaluation Metrics",table:{headers:["Metric","What it measures"],rows:[["Retrieval recall","Correct chunk in top-k"],["Answer relevance","Response addresses the user question"],["Faithfulness","Claims supported by retrieved text"],["Latency / cost","End-to-end SLA and token usage"]]},speakerNote:"Tie metrics to product SLAs, not just offline benchmarks.",titleIcon:"rag",conceptAnimation:"rag-pipeline"},{title:"Common Failure Modes",bullets:[{text:"Chunks too large — dilute relevance; too small — lose context.",icon:"idea"},{text:"Stale index — documents updated but embeddings not refreshed.",icon:"embedding"},{text:"ACL leaks — retrieving chunks the user should not see.",icon:"leakage"}],speakerNote:"Security slide — pause for questions on access control.",titleIcon:"idea"},{title:"RAG vs Fine-Tuning",table:{headers:["Approach","Best when","Tradeoff"],rows:[["RAG","Knowledge changes often; need citations","Retrieval quality is critical"],["Fine-tuning","Style/format/domain phrasing","Expensive refresh cycle"],["Both","Regulated domain + brand voice","Higher ops complexity"]]},speakerNote:"Most production systems start with RAG before fine-tuning.",titleIcon:"rag",conceptAnimation:"rag-pipeline"},{title:"Mini Lab — RAG Walkthrough",bullets:[{text:"Embed the user query and every document chunk.",icon:"embedding"},{text:"Retrieve the top chunk via similarity search.",icon:"rag"},{text:"Inject retrieved text into the LLM prompt before generation.",icon:"llm"}],speakerNote:"Walk the RAG loop conceptually; use a real embedding model in the hands-on lab.",titleIcon:"rag",conceptAnimation:"rag-pipeline"},{title:"Production Checklist",bullets:[{text:"Versioned ingestion pipeline with chunk + embed + index jobs.",icon:"embedding"},{text:"Observability: log queries, retrieved IDs, latency, user feedback.",icon:"rag"},{text:"Governance: PII scrubbing, retention policy, and access-controlled indexes.",icon:"idea"}],speakerNote:"Hand out checklist PDF or link — bridge to MLOps section next.",titleIcon:"idea"}];export{e as slides};
